"""Lay students out in rows, alphabetical by last name."""

from typing import Iterable, List
from rosterkit.models import Student
from operator import attrgetter

# ---
def seating_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    roster = sorted(students, key=attrgetter("last_name"))
    check_seating(roster, seats_per_row)
    return row_texts(roster, seats_per_row)

# ---
def check_seating(
    roster: List[Student], seats_per_row: int
) -> None:
    """Refuse an empty class or a seat count below one."""
    if seats_per_row <= 0:
        raise ValueError("seats per row must be positive")
    if not roster:
        raise ValueError("no students to seat")

# ---
def row_texts(
    roster: List[Student], width: int
) -> List[str]:
    starts = range(0, len(roster), width)
    return [
        row_text(number, roster[start:start + width])
        for number, start in enumerate(starts, 1)
    ]

# ---
def row_text(number: int, members: List[Student]) -> str:
    """One row as text, names in seating order."""
    text = " | ".join(item.display_name for item in members)
    return f"Row {number}: {text}"

