import unittest
from rosterkit.seating import seating_rows
from rosterkit.models import Student

# ---
def make_student(
    last_name: str, first_name: str
) -> Student:
    return Student(
        last_name + first_name, last_name, first_name, "A"
    )

class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Varrow", "Ines"),
            make_student("Dunmere", "Piet"),
            make_student("Halloway", "Juno"),
            make_student("Quillon", "Sefa"),
            make_student("Thistle", "Bram"),
        ]

    def test_rows_follow_last_name_order(self):
        lines = seating_rows(self.students, 2)
        self.assertEqual(
            lines,
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Quillon, Sefa | Thistle, Bram",
                "Row 3: Varrow, Ines",
            ],
        )

    def test_one_row_when_seats_cover_the_class(self):
        lines = seating_rows(self.students, 10)
        self.assertEqual(len(lines), 1)
        self.assertEqual(lines[0].count("|"), 4)

    def test_full_rows_have_no_empty_row(self):
        lines = seating_rows(self.students[:4], 2)
        self.assertEqual(len(lines), 2)

    def test_input_list_is_not_reordered(self):
        before = list(self.students)
        seating_rows(self.students, 2)
        self.assertEqual(self.students, before)

    def test_any_iterable_is_accepted(self):
        lines = seating_rows(iter(self.students), 2)
        expected = seating_rows(self.students, 2)
        self.assertEqual(lines, expected)

    def test_zero_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, 0)

    def test_negative_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, -3)

    def test_no_students_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
